function airPalette(model,enemy){return{body:enemy?'#795551':model.color,edge:enemy?'#bd8176':model.light,glass:enemy?'#e1a897':model.canopy,dark:'#10212b',accent:enemy?'#f78171':'#f0cf72',lamp:enemy?'#ff8067':'#f5e299'}}
function airPanel(points,p,shade=false){const ys=points.map(v=>v[1]),gradient=ctx.createLinearGradient(0,Math.min(...ys),0,Math.max(...ys));gradient.addColorStop(0,shade?p.edge:p.body);gradient.addColorStop(1,shade?p.body:p.dark);poly(points,gradient,p.dark,2.2);line(points[0][0],points[0][1],points[1][0],points[1][1],p.edge,1)}
function airGlass(points,p){const gradient=ctx.createLinearGradient(0,-40,40,18);gradient.addColorStop(0,p.glass);gradient.addColorStop(.55,'#395b67');gradient.addColorStop(1,'#162f3e');poly(points,gradient,p.dark,1.8);if(points.length>3)line(points[1][0],points[1][1],points.at(-1)[0],points.at(-1)[1],p.edge,1.2)}
function airWheel(x,y,r,rotation,p){circle(x,y,r,p.dark,p.edge);circle(x,y,r*.63,'#40535a');ctx.save();ctx.translate(x,y);ctx.rotate(rotation||0);for(let i=0;i<3;i++){ctx.rotate(Math.PI*2/3);line(1,0,r*.6,0,p.edge,1.3)}circle(0,0,1.8,p.accent);ctx.restore()}
function airGear(craft,model,gear,p){const heliType=model.family==='heli',r=heliType?10:7,rootY=heliType?16:12,stowedY=heliType?24:16,extendedY=heliType?60:34;for(const x of model.gear){const endX=x+(x<0?19:-16)*(1-gear),endY=stowedY+(extendedY-stowedY)*gear;line(x,rootY,endX,endY,p.dark,7);line(x+1,rootY,endX+1,endY,p.edge,2.5);line(x,rootY+3,endX+(x<0?8:-8),endY-5,p.body,3);airWheel(endX,endY,r,craft.wheel,p)}}
function airRotor(x,y,r,blades,phase,speed,p){ctx.save();ctx.translate(x,y);line(0,15,0,0,p.dark,7);line(1,14,1,0,p.edge,2);if(speed>.35){ctx.save();ctx.globalAlpha=.09*speed;ctx.beginPath();ctx.ellipse(0,0,r,7,0,0,Math.PI*2);ctx.fillStyle=p.accent;ctx.fill();ctx.restore()}for(let i=0;i<blades;i++){const a=phase+i*Math.PI*2/blades,c=Math.cos(a),s=Math.sin(a),tipX=c*r,tipY=s*7;poly([[c*9,s*2],[tipX,tipY-2],[tipX+c*8,tipY+2],[c*11,s*2+3]],i%2?p.body:p.dark,p.edge,.65);line(tipX-c*18,tipY,tipX,tipY,p.accent,2.8)}circle(0,0,5,p.edge,p.dark);const lx=Math.cos(phase)*22,ly=Math.sin(phase)*3;ctx.shadowBlur=8;ctx.shadowColor=p.lamp;circle(lx,ly,2,p.lamp);ctx.shadowBlur=0;ctx.restore()}
function airTailFan(x,y,r,phase,p,duct=false){if(duct){circle(x,y,r+6,p.body,p.dark);circle(x,y,r+1,p.dark,p.edge)}else{line(x,y,x+5,y-19,p.edge,3);circle(x,y,4,p.edge)}ctx.save();ctx.translate(x,y);ctx.rotate(phase);for(let i=0;i<4;i++){ctx.rotate(Math.PI/2);poly([[0,-2],[r-1,-5],[r,0],[2,4]],p.dark,p.edge,.7);rect(r-6,-4,5,4,p.accent)}circle(0,0,4,p.edge);ctx.restore()}
function airPod(x,y,count,p,rocket=false){ctx.save();ctx.translate(x,y);if(rocket){poly([[-20,-8],[14,-8],[21,0],[14,9],[-20,9]],p.body,p.dark,2);for(let i=0;i<Math.min(3,count);i++)circle(8,-5+i*5,2.4,p.dark,p.edge)}else{rect(-15,-7,31,13,p.dark);line(-12,-5,10,-5,p.edge,1.5);line(12,0,33,0,p.edge,4);rect(28,-3,7,6,p.dark)}ctx.restore()}
